"""Intake orchestration service (ticket #299).

``IntakeService.complete`` turns a finished intake wizard payload into the real-world
objects a firm needs: an account (new or an existing one matched by contact email), a
CRA-access record, an optional engagement (ProcessRun), and the two client-facing emails.
The whole thing runs in one transaction so a half-built account can never be left behind.

Documents are **engagement-driven** (tickets #307/#308): starting an engagement
instantiates its client tasks, which materialize step-linked ``DocumentRequest``s; the
intake no longer authors a document checklist. A no-engagement intake requests nothing.
The ``documents.send_request`` toggle just emails the already-materialized requests.

Payload shape (see ticket #299)::

    {
      "form_template": "<uuid>",
      "contact": {first_name, last_name, email, phone},
      "account": {name, client_type?, legal_name?, office?, tags?},
      "answers": {...},
      "cra": {has_cra_account: bool, send_instructions: bool},
      "documents": {send_request: bool},
      "engagement": {start: bool, template_id, start_date, due_date},
      "appointment_at": "iso?",
      "intake_id": "<uuid?>"
    }
"""
import logging

from django.db import transaction
from django.utils import timezone
from rest_framework import serializers

from app.clients.models import AccountContact, Client, Contact
from app.clients.api.serializers import ClientSerializer, normalize_phone
from app.documents.models import DocumentRequest
from app.compliance.services.run_instantiation_service import RunInstantiationService

from app.intake import emails
from app.intake.models import (
    ClientCRAAccess,
    CRAProgramAuthorization,
    Intake,
    IntakeFormTemplate,
)

logger = logging.getLogger(__name__)


class IntakeService:
    """Fat service: all intake-completion orchestration lives here."""

    @staticmethod
    @transaction.atomic
    def complete(payload, user):
        """Complete an intake. Returns a result dict; raises DRF ValidationError
        (field-shaped ``{field: [msg]}``) on bad input."""
        contact_data = payload.get('contact') or {}
        account_data = payload.get('account') or {}
        cra_data = payload.get('cra') or {}
        documents_data = payload.get('documents') or {}
        engagement_data = payload.get('engagement') or {}

        email = (contact_data.get('email') or '').strip().lower()

        form_template = IntakeService._resolve_form_template(payload.get('form_template'))

        # (a) Dedupe by contact email → attach or create.
        client, contact = IntakeService._resolve_client(
            email, contact_data, account_data, form_template,
        )

        emails_sent = []
        result = {'client_id': str(client.id)}

        # (b) CRA access record.
        cra_access = IntakeService._upsert_cra_access(client, cra_data, form_template, user)

        # (c) Engagement kickoff (+ optional board placement). Instantiation also
        # materializes the step-linked DocumentRequests for the engagement's client
        # tasks (ticket #307) — the engagement is the source of truth for docs.
        run = None
        if engagement_data.get('start'):
            run = IntakeService._start_engagement(client, engagement_data)
            result['run_id'] = str(run.id)
            board = IntakeService._place_on_board(run, engagement_data)
            if board is not None:
                result['board_id'] = str(board.id)

        # (d) Documents are engagement-driven (ticket #308): the intake no longer
        # authors a checklist. The requests come from instantiation (#307); a
        # no-engagement intake requests nothing. The "email request" toggle just
        # sends the already-materialized requests now (an explicit follow-up).
        doc_requests = (
            list(DocumentRequest.objects.filter(process_run=run).order_by('created_at'))
            if run is not None else []
        )
        result['document_request_ids'] = [str(d.id) for d in doc_requests]
        if documents_data.get('send_request') and doc_requests:
            recipient = contact.email if contact else client.email
            for doc_request in doc_requests:
                if emails.send_document_request_email(doc_request, recipient, from_user=user):
                    emails_sent.append('document_request')

        # (e) CRA instructions email — only for a firm with an authorization regime (MJ4 #585);
        # cra_access is None otherwise.
        if cra_access is not None and cra_data.get('send_instructions'):
            recipient = contact.email if contact else client.email
            programs = (form_template.cra_programs if form_template else []) or []
            if emails.send_cra_instructions_email(recipient, programs, from_user=user):
                emails_sent.append('cra_instructions')

        # (f) Mark the Intake COMPLETED.
        intake = IntakeService._finalize_intake(
            payload, client, form_template, user, contact=contact,
        )

        # (g) Best-effort push to Setmore (see _push_to_setmore). Must never roll
        # back or fail the intake — Kauby owns the slot; a Setmore failure is
        # expected/acceptable and degrades silently (logged).
        IntakeService._push_to_setmore(intake, contact_data)

        # cra_access is None for a jurisdiction with no authorization regime (MJ4 #585).
        result['cra_access_id'] = str(cra_access.id) if cra_access is not None else None
        result['emails_sent'] = emails_sent
        return result

    # ── helpers ────────────────────────────────────────────────────────────

    @staticmethod
    def _resolve_form_template(template_id):
        if not template_id:
            return None
        try:
            return IntakeFormTemplate.objects.get(id=template_id)
        except (IntakeFormTemplate.DoesNotExist, ValueError, TypeError):
            raise serializers.ValidationError(
                {'form_template': ['Unknown intake form template.']}
            )

    @staticmethod
    def _resolve_client(email, contact_data, account_data, form_template):
        """Resolve the contact and account EXPLICITLY from the payload (ticket #332).

        Contact↔Client is many-to-many (a person can hold a personal account AND
        one or more corporations), so we never silently pick a contact's first
        account. The caller must be explicit:

        Contact:
          - ``contact.id`` → load that Contact (skip email dedup).
          - else, reuse an exact existing Contact by email if one exists; else
            create a new one (as part of the new-account create below).

        Account:
          - ``account.id`` → attach to that existing Client, ensuring the resolved
            contact is linked via AccountContact (Primary contact).
          - else create a new Client via ClientSerializer, linking the resolved
            contact (existing → link_contact_ids, new → new_contacts).

        A contact that already has accounts but no explicit ``account.id`` and no
        new-account details is an error — we won't guess which account they mean.

        Returns ``(client, contact)``.
        """
        contact_id = contact_data.get('id')
        account_id = account_data.get('id')

        # ── Resolve the contact ─────────────────────────────────────────────
        existing_contact = None
        if contact_id:
            try:
                existing_contact = Contact.objects.get(id=contact_id)
            except (Contact.DoesNotExist, ValueError, TypeError):
                raise serializers.ValidationError({'contact': ['Unknown contact.']})
        elif email:
            existing_contact = Contact.objects.filter(email__iexact=email).first()

        # ── Attach to an explicitly-chosen existing account ─────────────────
        if account_id:
            try:
                client = Client.objects.get(id=account_id)
            except (Client.DoesNotExist, ValueError, TypeError):
                raise serializers.ValidationError({'account': ['Unknown account.']})

            contact = existing_contact
            if contact is None:
                # No id and no email match — materialize the new contact so we can
                # link it to the chosen account.
                contact = IntakeService._create_contact(contact_data)
            AccountContact.objects.get_or_create(
                account=client, contact=contact,
                defaults={'role': 'Primary contact'},
            )
            return client, contact

        # ── No explicit account: guard against silently picking one ─────────
        # If the contact already has accounts, the caller must choose one
        # (account.id) or provide new-account details — never auto-pick.
        has_new_account_data = bool(
            (account_data.get('name') or '').strip()
            or account_data.get('legal_name')
        )
        if (
            existing_contact is not None
            and existing_contact.linked_accounts.exists()
            and not has_new_account_data
        ):
            raise serializers.ValidationError(
                {'account': ['Choose an existing account or provide new account details.']}
            )

        # ── Create a new account, linking the resolved/new contact ──────────
        if existing_contact is not None:
            client = IntakeService._create_client(
                account_data, form_template, link_contact=existing_contact,
            )
            return client, existing_contact

        client = IntakeService._create_client(
            account_data, form_template, new_contact=contact_data,
        )
        contact = (
            Contact.objects.filter(linked_accounts__account=client)
            .order_by('created_at')
            .first()
        )
        return client, contact

    @staticmethod
    def _create_contact(contact_data):
        """Create a standalone Contact from new-contact payload fields."""
        nc = contact_data or {}
        contact = Contact.objects.create(
            first_name=nc.get('first_name', ''),
            last_name=nc.get('last_name', ''),
            email=(nc.get('email') or '').strip(),
            phone=normalize_phone(nc.get('phone', '')) or '',
        )
        return contact

    @staticmethod
    def _create_client(account_data, form_template, new_contact=None, link_contact=None):
        """Create a Client via ClientSerializer, reusing its contact create/link path."""
        client_type = (
            account_data.get('client_type')
            or (form_template.client_type if form_template else None)
            or 'COMPANY'
        )
        data = {
            'name': account_data.get('name') or '',
            'client_type': client_type,
            'status': 'ACTIVE',
        }
        if account_data.get('office'):
            data['office'] = account_data['office']
        if account_data.get('tags'):
            data['tags'] = account_data['tags']
        if client_type == 'COMPANY':
            data['company_profile'] = {'legal_name': account_data.get('legal_name') or ''}

        if link_contact is not None:
            data['link_contact_ids'] = [str(link_contact.id)]
        else:
            nc = new_contact or {}
            data['new_contacts'] = [{
                'first_name': nc.get('first_name', ''),
                'last_name': nc.get('last_name', ''),
                'email': (nc.get('email') or '').strip(),
                'phone': nc.get('phone', ''),
            }]

        serializer = ClientSerializer(data=data)
        serializer.is_valid(raise_exception=True)
        return serializer.save()

    @staticmethod
    def _upsert_cra_access(client, cra_data, form_template, user):
        # A CRA/authority record is created only when BOTH axes agree (MJ4 #585 + V3 #599):
        #   * the firm's JURISDICTION has an authorization regime (e.g. CA/CRA), and
        #   * the firm's VERTICAL declares it does tax-authority authorizations (`cra_authorizations`).
        # So an immigration firm in CA (regime exists, but the vertical doesn't do authorizations)
        # creates no record — the two gates are independent and both must hold.
        from django.db import connection
        from app.common.authorization_regimes import current_regime
        from app.common.verticals import firm_has_capability
        if current_regime() is None or not firm_has_capability(
                getattr(connection, 'tenant', None), 'cra_authorizations'):
            return None

        send_instructions = bool(cra_data.get('send_instructions'))
        defaults = {
            'has_cra_account': cra_data.get('has_cra_account'),
            'updated_by': user if getattr(user, 'is_authenticated', False) else None,
        }
        cra_access, _created = ClientCRAAccess.objects.get_or_create(
            client=client, defaults=defaults,
        )
        if not _created:
            if cra_data.get('has_cra_account') is not None:
                cra_access.has_cra_account = cra_data.get('has_cra_account')
            if defaults['updated_by'] is not None:
                cra_access.updated_by = defaults['updated_by']

        if form_template and form_template.cra_programs and not cra_access.programs:
            cra_access.programs = list(form_template.cra_programs)

        if send_instructions:
            cra_access.rep_status = ClientCRAAccess.RepStatus.INSTRUCTIONS_SENT
            cra_access.instructions_sent_at = timezone.now()

        cra_access.save()
        IntakeService._sync_program_auths(cra_access, send_instructions)
        return cra_access

    @staticmethod
    def _sync_program_auths(cra_access, send_instructions):
        """Create/sync a per-program CRAProgramAuthorization for each program on the
        access record. Idempotent (get_or_create per program). New rows land in
        INSTRUCTIONS_SENT (+ timestamp) when instructions went out, else NOT_REQUESTED.
        Only fresh rows are touched — an already-advanced program is left untouched."""
        now = timezone.now()
        for program in (cra_access.programs or []):
            auth, created = CRAProgramAuthorization.objects.get_or_create(
                cra_access=cra_access, program=program,
            )
            if created and send_instructions:
                auth.status = ClientCRAAccess.RepStatus.INSTRUCTIONS_SENT
                auth.instructions_sent_at = now
                auth.save(update_fields=['status', 'instructions_sent_at', 'updated_at'])

    @staticmethod
    def _start_engagement(client, engagement_data):
        template_id = engagement_data.get('template_id')
        if not template_id:
            raise serializers.ValidationError(
                {'engagement': {'template_id': ['This field is required to start an engagement.']}}
            )
        start_date = engagement_data.get('start_date')
        due_date = engagement_data.get('due_date')
        if not start_date or not due_date:
            raise serializers.ValidationError(
                {'engagement': ['start_date and due_date are required to start an engagement.']}
            )
        try:
            return RunInstantiationService.instantiate(
                template_id=template_id,
                client_id=client.id,
                start_date=start_date,
                due_date=due_date,
            )
        except Exception:  # ProcessTemplate.DoesNotExist etc. → field-shaped 400
            logger.exception("Engagement instantiation failed for client %s", client.id)
            raise serializers.ValidationError(
                {'engagement': ['Could not start the engagement.']}
            )

    @staticmethod
    def _place_on_board(run, engagement_data):
        """Place the run on a board — an existing ``board_id`` or a new board from
        ``new_board_name``. Returns the Board, or None if neither was given (the
        engagement is created but left unplaced, to be boarded later)."""
        from app.compliance.models import Board, BoardColumn, BoardEngagement

        board_id = engagement_data.get('board_id')
        new_board_name = (engagement_data.get('new_board_name') or '').strip()

        if board_id:
            try:
                board = Board.objects.get(id=board_id)
            except (Board.DoesNotExist, ValueError, TypeError):
                raise serializers.ValidationError({'engagement': {'board_id': ['Board not found.']}})
        elif new_board_name:
            board = Board.objects.create(name=new_board_name, board_type='ENGAGEMENT')
        else:
            return None

        # A board needs at least one column to hold a placement.
        column = board.columns.order_by('order').first()
        if column is None:
            column = BoardColumn.objects.create(board=board, name='Not Started', order=0)

        BoardEngagement.objects.get_or_create(
            board=board, engagement=run,
            defaults={'column': column, 'order': board.board_engagements.count()},
        )
        return board

    @staticmethod
    def _finalize_intake(payload, client, form_template, user, contact=None):
        intake_id = payload.get('intake_id')
        contact_data = payload.get('contact') or {}
        by = user if getattr(user, 'is_authenticated', False) else None

        appointment_at = payload.get('appointment_at') or None
        # A brand-new contact carries its name inline; a returning contact is sent as
        # ``{ id }`` only, so fall back to the resolved Contact's display name (then the
        # client name) — otherwise the intake row shows a blank prospect (#504).
        prospect_name = (
            f"{contact_data.get('first_name', '')} {contact_data.get('last_name', '')}"
        ).strip()
        if not prospect_name and contact is not None:
            prospect_name = (contact.display_name or '').strip()
        if not prospect_name and client is not None:
            prospect_name = (client.name or '').strip()

        if intake_id:
            try:
                intake = Intake.objects.get(id=intake_id)
            except (Intake.DoesNotExist, ValueError, TypeError):
                raise serializers.ValidationError({'intake_id': ['Unknown intake.']})
        else:
            intake = Intake(source=Intake.Source.MANUAL, created_by=by)

        intake.status = Intake.Status.COMPLETED
        intake.created_client = client
        intake.form_template = form_template
        intake.answers = payload.get('answers') or intake.answers or {}
        if prospect_name:
            intake.prospect_name = prospect_name
        email = contact_data.get('email') or (contact.email if contact is not None else '')
        if email:
            intake.prospect_email = email
        phone = contact_data.get('phone') or (contact.phone if contact is not None else '')
        if phone:
            intake.prospect_phone = normalize_phone(phone) or phone
        if appointment_at:
            intake.appointment_at = appointment_at
        intake.save()
        return intake

    @staticmethod
    def _push_to_setmore(intake, contact_data):
        """Best-effort push of a MANUAL intake's customer + appointment to Setmore.

        ⚠️ The Setmore write API is UNCONFIRMED. This is fire-and-forget: Kauby owns
        the slot, so any failure (network, 4xx/5xx, missing creds) is expected and
        must degrade silently — we log it and move on. Never raises. Any returned
        keys are stored back on the Intake so a later sync can reconcile.

        Only runs for MANUAL intakes that have an appointment_at and some contact
        info; SETMORE-sourced intakes already exist upstream, so we don't echo them
        back.
        """
        if intake is None or intake.source != Intake.Source.MANUAL:
            return
        if not intake.appointment_at:
            return

        email = (contact_data.get('email') or intake.prospect_email or '').strip()
        phone = (contact_data.get('phone') or intake.prospect_phone or '').strip()
        if not email and not phone:
            return

        try:
            from app.integrations.client import SetmoreClient

            client = SetmoreClient()
            if not client.credential:
                logger.info('Setmore not connected; skipping push for intake %s', intake.id)
                return

            first = contact_data.get('first_name') or ''
            last = contact_data.get('last_name') or ''
            if not (first or last) and intake.prospect_name:
                parts = intake.prospect_name.split(' ', 1)
                first = parts[0]
                last = parts[1] if len(parts) > 1 else ''

            customer_key = intake.setmore_customer_key
            if not customer_key:
                resp = client.create_customer(
                    first_name=first, last_name=last, email=email, phone=phone,
                )
                customer_key = _setmore_key(resp, 'customer')

            start_iso = intake.appointment_at.isoformat()
            appt_resp = client.create_appointment(
                customer_key=customer_key or '',
                start_time=start_iso,
            )
            appointment_key = _setmore_key(appt_resp, 'appointment')

            update_fields = []
            if customer_key and customer_key != intake.setmore_customer_key:
                intake.setmore_customer_key = str(customer_key)
                update_fields.append('setmore_customer_key')
            if appointment_key and appointment_key != intake.setmore_appointment_id:
                intake.setmore_appointment_id = str(appointment_key)
                update_fields.append('setmore_appointment_id')
            if update_fields:
                update_fields.append('updated_at')
                intake.save(update_fields=update_fields)
        except Exception:
            # Expected/acceptable — Kauby owns the slot. Log and swallow.
            logger.warning(
                'Best-effort Setmore push failed for intake %s (ignored)',
                intake.id, exc_info=True,
            )


def _setmore_key(resp, kind):
    """Pull a created object's key out of Setmore's inconsistent write response."""
    if not isinstance(resp, dict):
        return ''
    inner = resp.get('data', resp)
    if isinstance(inner, dict):
        obj = inner.get(kind, inner)
        if isinstance(obj, dict):
            return obj.get('key') or obj.get('id') or ''
    return ''

